from pathlib import Path
path=Path('app/system/production/ReportScreens.tsx')
code=path.read_text(encoding='utf-8')
code=code.replace('const textOf = (value: unknown) => typeof value === "string" || typeof value === "number" ? String(value) : "";\n','')
anchor='function ReportDetail('
position=code.index(anchor)
components='''function ReportDocumentHeader({ report, title, reportDate, onTitle, onDate }: { report: ReportRecord; title: string; reportDate: string; onTitle?: (value: string) => void; onDate?: (value: string) => void }) {
  return <header className="report-paper-header">
    <div className="report-paper-masthead"><strong>TOMAS TECH</strong><div><h2>{labels[report.reportType].toUpperCase()} REPORT</h2><span>{report.reportType === "UAT" ? "ใบรายงานการทดสอบและตรวจรับงาน" : report.reportType === "SERVICE" ? "ใบรายงานการให้บริการ" : "ใบรายงานผลการดำเนินงาน"}</span></div><small>{report.reportType === "UAT" ? "อ้างอิง TT-FRM-UAT-001 · Rev.00" : ["SERVICE", "INSTALLATION"].includes(report.reportType) ? "อ้างอิง TT-FRM-SRV-001 · Rev.00" : "แบบรายงานมาตรฐานทีม"}</small></div>
    <div className="report-paper-meta"><div><span>REPORT NO. / เลขที่</span><strong>{report.number} · R{report.revision}</strong></div><div><span>REPORT DATE / วันที่</span>{onDate ? <input aria-label="Report date" type="date" required value={reportDate} onChange={event => onDate(event.target.value)} /> : <strong>{reportDate}</strong>}</div><div><span>STATUS / สถานะ</span><strong>{labels[report.status] ?? report.status}</strong></div><div className="wide"><span>CUSTOMER / ลูกค้า</span><strong>{report.customer}</strong></div><div><span>PROJECT / INQUIRY NO.</span><strong>{report.sourceReference}</strong></div><div className="full"><span>PROJECT / SITE / โครงการ</span><strong>{report.sourceTitle}</strong></div><div className="full"><span>REPORT TITLE / เรื่อง</span>{onTitle ? <input aria-label="Report title" required maxLength={500} value={title} onChange={event => onTitle(event.target.value)} /> : <strong>{title}</strong>}</div></div>
  </header>;
}

function ReportSignatureSummary({ report }: { report: ReportRecord }) {
  const people = [{ stage: "PREPARE", label: "ผู้จัดทำ / Prepared by", person: report.preparedBy }, ...(report.reviewerId ? [{ stage: "REVIEW", label: "ผู้ตรวจ / Reviewed by", person: report.reviewer }] : []), { stage: "APPROVE", label: "ผู้อนุมัติ / Approved by", person: report.approver }];
  return <section className="report-paper-signoff"><h3>ACKNOWLEDGEMENT / การลงนามและรับทราบ</h3><div className="report-paper-signatures">{people.map(person => { const signature = report.signatures.find(item => item.stage === person.stage); return <div key={person.stage}><h4>{person.label}</h4><strong>{signature?.actorName ?? person.person?.name ?? "ยังไม่ระบุ"}</strong><p>{signature ? "ลงนามในระบบแล้ว" : person.stage === "REVIEW" && ["REVIEWED", "APPROVED", "AWAITING_CUSTOMER", "COMPLETED"].includes(report.status) ? "ตรวจแล้ว (ไม่ได้ลงนาม)" : "ยังไม่ได้ลงนาม"}</p><small>{signature ? new Date(signature.occurredAt).toLocaleString("th-TH") : "วันที่: —"}</small></div>; })}<div><h4>ตัวแทนลูกค้า / Customer</h4>{report.customerAcknowledgment ? <CustomerAcknowledgmentView acknowledgment={report.customerAcknowledgment} /> : <><strong>รอลูกค้ารับทราบ</strong><p>ส่งลิงก์ให้ลูกค้าหลังอนุมัติรายงาน</p><small>วันที่: —</small></>}</div></div><p className="report-signoff-note">ลายเซ็นและการรับทราบในส่วนนี้มาจากขั้นตอนลงนามของรายงานฉบับนี้</p></section>;
}

'''
code=code[:position]+components+code[position:]
code=code.replace('  const [templateSeed, setTemplateSeed] = useState<TemplateSeed | null>(null);','  const [templateSeed, setTemplateSeed] = useState<TemplateSeed | null>(null);\n  const [preview, setPreview] = useState(false);')
code=code.replace('<form onSubmit={event => {\n      event.preventDefault(); if (step !== 2 || busy) return;', '<form noValidate={step === 1} onSubmit={event => {\n      event.preventDefault(); if (step !== 2 || busy) return;')
old='''      {tab === "content" ? <><div className="report-fields"><Field label="Title">{editable ? <input aria-label="Report title" required maxLength={500} value={draft.title} onChange={event => patch({ title: event.target.value })} /> : <div className="report-value">{report.title}</div>}</Field><Field label="Report date">{editable ? <input aria-label="Report date" required type="date" value={draft.reportDate} onChange={event => patch({ reportDate: event.target.value })} /> : <div className="report-value">{report.reportDate}</div>}</Field></div><ReportBodyEditor reportType={report.reportType} body={draft.body} readOnly={!editable || busy} onChange={body => patch({ body })} /></> : null}'''
new='''      {tab === "content" ? <><div className="report-document-tools"><div><strong>{preview || !editable ? "มุมมองเอกสาร" : "กรอกในแบบฟอร์ม"}</strong><span>{editable ? "ช่อง * ต้องกรอกก่อนส่งอนุมัติ · บันทึกฉบับร่างไว้ก่อนได้" : "รายงานฉบับนี้อ่านได้อย่างเดียว"}</span></div><div>{editable ? <button className="btn default" type="button" onClick={() => setPreview(value => !value)}>{preview ? "กลับไปกรอก" : "ดูตัวอย่างเอกสาร"}</button> : null}{editable ? <button className="btn primary" type="button" disabled={busy || !dirty || !draft.title.trim() || !draft.reportDate || !draft.approverId} onClick={() => void changeAction("save")}>{busy ? "กำลังบันทึก…" : "บันทึกฉบับร่าง"}</button> : null}</div></div><div className="report-paper"><ReportDocumentHeader report={report} title={draft.title} reportDate={draft.reportDate} onTitle={editable && !preview && !busy ? title => patch({ title }) : undefined} onDate={editable && !preview && !busy ? reportDate => patch({ reportDate }) : undefined} /><ReportBodyEditor reportType={report.reportType} body={draft.body} readOnly={!editable || preview || busy} onChange={body => patch({ body })} /><ReportSignatureSummary report={report} /></div></> : null}'''
assert old in code
code=code.replace(old,new)
start=code.index('    <article className="report-print">')
end=code.index('</article>',start)+len('</article>')
code=code[:start]+'''    <article className="report-print"><ReportDocumentHeader report={report} title={report.title} reportDate={report.reportDate} />{report.template ? <p>Template: {report.template.name} · V{report.template.version}</p> : null}<ReportBodyEditor reportType={report.reportType} body={report.body} readOnly /><ReportSignatureSummary report={report} /></article>'''+code[end:]
path.write_text(code,encoding='utf-8')
